            color: #1e1e2e;
            box-shadow: 0 8px 25px rgba(255,107,53,0.4);
        }

        /* Carrinho detalhado */
        .cart-panel {
            position: fixed;
            bottom: 24px;
            right: 24px;
            width: 340px;
            max-height: 420px;
            background: #fff;
            border-radius: 15px;
            box-shadow: 0 8px 30px rgba(0,0,0,0.25);
            z-index: 1001;
            display: none;
            flex-direction: column;
            overflow-y: auto;
            transform: translateY(20px);
            transition: transform 0.3s;
        }

        .cart-panel.open {
            display: flex;
            transform: translateY(0);
        }

        .cart-header {
            background: #1e1e2e;
            color: #fff;
            padding: 16px;
            display: flex;
            justify-content: space-between;
