            font-size: 1.1rem;
            margin-bottom: 14px;
        }

        .btn-order {
            width: 100%;
            background: #1e1e2e;
            color: #fff;
            border: none;
            padding: 14px;
            border-radius: 10px;
            font-size: 1rem;
            cursor: pointer;
            transition: background 0.2s;
        }

        .btn-order:hover { background: #2d2d44; }

        footer {
            margin-top: 30px;
            text-align: center;
            color: #777;
            padding: 20px;
            font-size: 0.85rem;
        }

        /* Toast de confirmação */
        .toast {
            position: fixed;
            top: 20px;
            left: 50%;
            transform: translateX(-50%) translateY(-80px);
            background: #2e7d32;
            color: #fff;
            padding: 12px 24px;
            border-radius: 8px;
            font-weight: 600;
            z-index: 9999;
            transition: transform 0.3s;
            opacity: 0;
        }

        .toast.show {
            transform: translateX(-50%) translateY(0);
            opacity: 1;
        }

        @media (max-width: 768px) {
            body { flex-direction: column; }
