        <div class="categoria">
            <h2>Bebidas</h2>
            <div class="produto" onclick="addProduct('Refrigerante Cola 500ml', 'Gelado e refrescante.', 9.90)">
                <div class="produto-info">
                    <div class="produto-name">Refrigerante Cola 500ml</div>
                    <div class="produto-desc">Gelado e refrescante.</div>
                </div>
                <span class="produto-price">R$ 9,90</span>
