# Adicionando compressão Zstd ao seu código zlib

Vou te mostrar como adicionar uma função de compressão **Zstd** ao seu projeto, mantendo o padrão do seu `Zlib` class. Também vou sugerir algumas boas práticas.

---

## 1. Pré-requisitos

Você precisa ter a biblioteca **libzstd** disponível. Exemplos de inclusão:

```cmake
find_package(Zstd REQUIRED)   # ou pkg-config --cflags=zstd
target_link_libraries(yourproj PRIVATE Zstd::Zstd)
```

Ou no `Makefile`:

```makefile
LDFRAGMENTS = -lzstd
```

---

## 2. Nova classe `Zstd` (ou método dentro da sua classe existente)

Aqui está uma implementação completa seguindo o estilo do seu `Zlib`:

```cpp
#include "zstd.hpp"          // ou whatever você chamar
#include <cstdint>
#include <cstring>

class Zstd {
public:
    /// Comprime dados usando Zstd e retorna o tamanho do buffer de saída.
    /// Retorna -1 em caso de erro.
    static int Compress(uint8_t* dest, uint32_t* destLen,
                        const uint8_t* source, uint32_t sourceLen) {
        if (sourceLen == 0) {
            // Se não há dados, buffer vazio é suficiente
            *destLen = 0;
            return 0;
        }

        // Determinar nível de compressão (0 = rápido, 19 = melhor)
        int level = 3; // ajuste conforme necessidade

        zstd_compress_st ctx;
        memset(&ctx, 0, sizeof(ctx));

        ctx.level = level;
        ctx.bind_ccontext(NULL); // sem contexto compartilhado

        // Ajuste inicial para estimar tamanho
        size_t estimate = ZSTD_CBound(sourceLen, level);
        dest = new (std::align_val_t{}) uint8_t[estimate];
        *destLen = estimate;

        int ret = ZSTD_compress(
            &ctx,
            dest,
            static_cast<size_t>(*destLen),
            source,
            sourceLen,
            ZSTD_D_DEFAULTCOST
        );

        if (ret != Z_OK && ret != Z_STREAM_END) {
            delete[] dest;
            return -1;
        }

        // Se sobrou espaço, tente aumentar qualidade
        if (ret == Z_STREAM_END) {
            size_t used = static_cast<size_t>(ctx.out_size);
            if (used < *destLen) {
                // Ajuste fino — opcional, mas melhora taxa de compressão
                uint8_t* extra = new (std::align_val_t{})
                    uint8_t[*destLen - used];
                ret = ZSTD_compress(&ctx, extra,
                                    *destLen - used,
                                    nullptr, 0,
                                    ZSTD_D_ULTRA);
                if (ret == Z_OK || ret == Z_STREAM_END) {
                    *destLen = used + std::min(static_cast<uint32_t>(extra),
                                               *destLen - used);
                    // Na prática, copie os bytes para dest realocada...
                    // Para simplicidade, alocamos novamente abaixo
                } else {
                    delete[] extra;
                }
            }
        }

        *destLen = static_cast<uint32_t>(ctx.out_size);
        return 0;
    }

    /// Descomprime dados Zstd com destino especificado.
    static int Uncompress(uint8_t* dest, uint32_t* destLen,
                          const uint8_t* source, uint32_t sourceLen) {
        if (sourceLen == 0) {
            *destLen = 0;
            return 0;
        }

        zstd_decompress_st ctx;
        memset(&ctx, 0, sizeof(ctx));

        // Estimativa inicial de tamanho
        size_t estimate = ZSTD_uncompressedSize(ZSTD_getFrameHeader(source, sourceLen));
        if (estimate == 0) {
            // Fallback conservador
            estimate = static_cast<size_t>(sourceLen) * 2;
        }

        dest = new (std::align_val_t{}) uint8_t[estimate];
        *destLen = estimate;

        int ret = ZSTD_decompressStream(
            &ctx,
            dest,
            static_cast<size_t>(*destLen),
            source,
            sourceLen
        );

        if (ret != Z_OK && ret != Z_STREAM_END) {
            delete[] dest;
            return -1;
        }

        // Limpa eventual excesso
        while (*destLen > ctx.out_size && ctx.err == Z_OK) {
            // Não dá pra "cortar" facilmente sem realloc; normalmente
            // o consumidor já sabe que só precisa até ctx.out_size
        }

        *destLen = static_cast<uint32_t>(ctx.out_size);
        return 0;
    }

private:
    // destruidora implícita para evitar cópias
};
```

> ⚠️ **Atenção**: o snippet acima tem um pequeno detalhe de "ajuste fino" que pode ficar confuso. Vou simplificar na versão final.

---

## Versão mais limpa e segura

### Função de compressão

```cpp
int Zstd::Compress(uint8_t* dest, uint32_t* destLen,
                   const uint8_t* source, uint32_t sourceLen)
{
    if (sourceLen == 0) {
        *destLen = 0;
        return 0;
    }

    int level = 3; // 0=rápido ... 19=melhor
    zstd_compress_st ctx;
    memset(&ctx, 0, sizeof(ctx));
    ctx.level = level;

    // Estima tamanho de saída
    size_t est = ZSTD_CBound(sourceLen, level);
    dest = static_cast<uint8_t*>(malloc(est));
    if (!dest) return -1;

    *destLen = static_cast<uint32_t>(est);

    int ret = ZSTD_compress(&ctx, dest, *destLen,
                            source, sourceLen,
                            ZSTD_D_DEFAULTCOST);

    if (ret != Z_OK && ret != Z_STREAM_END) {
        free(dest);
        return -1;
    }

    *destLen = static_cast<uint32_t>(ctx.out_size);
    return 0;
}
```

### Função de descompressão (equivalente à sua `NormalUncompress`)

```cpp
int Zstd::Uncompress(uint8_t* dest, uint32_t* destLen,
                     const uint8_t* source, uint32_t sourceLen)
{
    if (sourceLen == 0) {
        *destLen = 0;
        return 0;
    }

    zstd_decompress_st ctx;
    memset(&ctx, 0, sizeof(ctx));

    // Tenta descobrir tamanho original via header
    auto hdrLen = ZSTD_getFrameHeaderLength(source, sourceLen);
    size_t estimate = (hdrLen == 0 ? 0 : hdrLen) + sourceLen * 2;
    dest = static_cast<uint8_t*>(malloc(estimate));
    if (!dest) return -1;

    *destLen = static_cast<uint32_t>(estimate);

    int ret = ZSTD_decompressStream(&ctx, dest, *destLen,
                                    source, sourceLen);

    if (ret != Z_OK && ret != Z_STREAM_END) {
        free(dest);
        return -1;
    }

    *destLen = static_cast<uint32_t>(ctx.out_size);
    free(dest); // já liberamos, mas mantém o padrão se quiser reutilizar
    // Obs: se quiser manter o ponteiro, deixe malloc e libere só quando terminar
    return 0;
}
```

---

## 3. Integre com sua classe `Zlib` existente

Se quiser juntar tudo numa única classe híbrida:

```cpp
class Codec {
public:
    // ... seus métodos zlib existentes ...

    // Compressão Zstd
    static int Compress(const uint8_t* src, uint32_t srcLen,
                        uint8_t* dst, uint32_t& dstLen, int level = 3)
    {
        return Zstd::Compress(dst, &dstLen, src, srcLen);
    }

    // Descompressão Zstd
    static int Uncompress(const uint8_t* src, uint32_t srcLen,
                          uint8_t* dst, uint32_t& dstLen)
    {
        return Zstd::Uncompress(dst, &dstLen, src, srcLen);
    }

    // Descompressão Zlib (sua função adaptada)
    static int Uncompress(const uint8_t* src, uint32_t srcLen,
                          uint8_t* dst, uint32_t& dstLen)
    {
        return Zlib::NormalUncompress(dst, &dstLen, src, srcLen);
    }
};
```

---

## 4. Dicas importantes

| Ponto | Recomendação |
|-------|--------------|
| **Memória** | Use `new`/`delete` ou `malloc`/`free`, mas prefira **buffers gerenciados por stack/pool** em loops críticos |
| **Contexto** | Para compressões repetidas do mesmo fluxo, use `zstd_compress_ctx` / `zstd_decompress_ctx` para reutilizar estado |
| **Nível** | Comece com `level=3`; ajuste depois conforme trade-off velocidade × tamanho |
| **Formato** | Formato blocklist vs dict — para compatibilidade ampla, use **blocklist** (padrão) |
