```cpp
#include "zstd.hpp"          // ou whatever você chamar
#include <cstdint>
#include <cstring>

class Zstd {
public:
    /// Comprime dados usando Zstd e retorna o tamanho do buffer de saída.
    /// Retorna -1 em caso de erro.
    static int Compress(uint8_t* dest, uint32_t* destLen,
                        const uint8_t* source, uint32_t sourceLen) {
        if (sourceLen == 0) {
            // Se não há dados, buffer vazio é suficiente
            *destLen = 0;
            return 0;
        }

        // Determinar nível de compressão (0 = rápido, 19 = melhor)
        int level = 3; // ajuste conforme necessidade

        zstd_compress_st ctx;
        memset(&ctx, 0, sizeof(ctx));

        ctx.level = level;
        ctx.bind_ccontext(NULL); // sem contexto compartilhado

        // Ajuste inicial para estimar tamanho
        size_t estimate = ZSTD_CBound(sourceLen, level);
        dest = new (std::align_val_t{}) uint8_t[estimate];
        *destLen = estimate;

        int ret = ZSTD_compress(
            &ctx,
            dest,
            static_cast<size_t>(*destLen),
            source,
            sourceLen,
            ZSTD_D_DEFAULTCOST
        );

        if (ret != Z_OK && ret != Z_STREAM_END) {
            delete[] dest;
            return -1;
        }

        // Se sobrou espaço, tente aumentar qualidade
        if (ret == Z_STREAM_END) {
            size_t used = static_cast<size_t>(ctx.out_size);
            if (used < *destLen) {
                // Ajuste fino — opcional, mas melhora taxa de compressão
                uint8_t* extra = new (std::align_val_t{})
                    uint8_t[*destLen - used];
                ret = ZSTD_compress(&ctx, extra,
                                    *destLen - used,
                                    nullptr, 0,
                                    ZSTD_D_ULTRA);
                if (ret == Z_OK || ret == Z_STREAM_END) {
                    *destLen = used + std::min(static_cast<uint32_t>(extra),
                                               *destLen - used);
                    // Na prática, copie os bytes para dest realocada...
                    // Para simplicidade, alocamos novamente abaixo
                } else {
                    delete[] extra;
                }
            }
        }

        *destLen = static_cast<uint32_t>(ctx.out_size);
        return 0;
    }

    /// Descomprime dados Zstd com destino especificado.
    static int Uncompress(uint8_t* dest, uint32_t* destLen,
                          const uint8_t* source, uint32_t sourceLen) {
        if (sourceLen == 0) {
            *destLen = 0;
            return 0;
        }

        zstd_decompress_st ctx;
        memset(&ctx, 0, sizeof(ctx));

        // Estimativa inicial de tamanho
        size_t estimate = ZSTD_uncompressedSize(ZSTD_getFrameHeader(source, sourceLen));
        if (estimate == 0) {
            // Fallback conservador
            estimate = static_cast<size_t>(sourceLen) * 2;
        }

        dest = new (std::align_val_t{}) uint8_t[estimate];
        *destLen = estimate;

        int ret = ZSTD_decompressStream(
            &ctx,
            dest,
            static_cast<size_t>(*destLen),
            source,
            sourceLen
        );

        if (ret != Z_OK && ret != Z_STREAM_END) {
            delete[] dest;
            return -1;
        }

        // Limpa eventual excesso
        while (*destLen > ctx.out_size && ctx.err == Z_OK) {
            // Não dá pra "cortar" facilmente sem realloc; normalmente
            // o consumidor já sabe que só precisa até ctx.out_size
        }

        *destLen = static_cast<uint32_t>(ctx.out_size);
        return 0;
    }

private:
    // destruidora implícita para evitar cópias
};
```

