```cpp
class Codec {
public:
    // ... seus métodos zlib existentes ...

    // Compressão Zstd
    static int Compress(const uint8_t* src, uint32_t srcLen,
                        uint8_t* dst, uint32_t& dstLen, int level = 3)
    {
        return Zstd::Compress(dst, &dstLen, src, srcLen);
    }

    // Descompressão Zstd
    static int Uncompress(const uint8_t* src, uint32_t srcLen,
                          uint8_t* dst, uint32_t& dstLen)
    {
        return Zstd::Uncompress(dst, &dstLen, src, srcLen);
    }

    // Descompressão Zlib (sua função adaptada)
    static int Uncompress(const uint8_t* src, uint32_t srcLen,
                          uint8_t* dst, uint32_t& dstLen)
    {
        return Zlib::NormalUncompress(dst, &dstLen, src, srcLen);
    }
};
